#import "native_midi.hpp"
#include "native_async.hpp"
#import "native_style.hpp"
using vj::Json;
static NSString* midiText(const std::string& v){return [NSString stringWithUTF8String:v.c_str()];}
static NSTextField* midiLabel(NSString* text){auto label=[NSTextField labelWithString:text];label.font=vj::style::font(12);return label;}
static void midiSize(NSControl* control,CGFloat width=0){[control.heightAnchor constraintEqualToConstant:vj::style::controlHeight].active=YES;if(width>0)[control.widthAnchor constraintEqualToConstant:width].active=YES;}
static NSStackView* midiStack(bool horizontal=false){auto* v=[[NSStackView alloc]init];v.orientation=horizontal?NSUserInterfaceLayoutOrientationHorizontal:NSUserInterfaceLayoutOrientationVertical;v.alignment=horizontal?NSLayoutAttributeCenterY:NSLayoutAttributeLeading;v.spacing=8;return v;}
@interface VJMidiAction : NSButton { @public Json command; }
@end
@implementation VJMidiAction
@end
@implementation VJMidiControls {
 vj::Model* _model;NSStackView* _root;NSTextField* _status;NSPopUpButton* _devices;NSPopUpButton* _kind;NSPopUpButton* _target;NSStackView* _mappings;std::vector<Json> _targets;std::string _learnKind;uint64_t _revision;uint64_t _runtimeRevision;bool _building;
}
- (instancetype)initWithFrame:(NSRect)frame model:(vj::Model*)model {
 if((self=[super initWithFrame:frame])){_model=model;_revision=UINT64_MAX;_learnKind="mix_master";_root=midiStack();_root.translatesAutoresizingMaskIntoConstraints=NO;[self addSubview:_root];[NSLayoutConstraint activateConstraints:@[[_root.topAnchor constraintEqualToAnchor:self.topAnchor],[_root.bottomAnchor constraintEqualToAnchor:self.bottomAnchor],[_root.leadingAnchor constraintEqualToAnchor:self.leadingAnchor],[_root.trailingAnchor constraintEqualToAnchor:self.trailingAnchor]]];
 _status=midiLabel(@"");_status.textColor=vj::style::secondary();auto* devices=midiStack(true);auto inputLabel=midiLabel(@"MIDI input");[inputLabel.widthAnchor constraintEqualToConstant:vj::style::formLabel].active=YES;[devices addArrangedSubview:inputLabel];_devices=[[VJPopup alloc]initWithFrame:NSZeroRect pullsDown:NO];midiSize(_devices,260);_devices.target=self;_devices.action=@selector(deviceChanged:);[devices addArrangedSubview:_devices];[devices addArrangedSubview:[self button:@"Scan" command:{{"action","midi_scan"}}]];_status.lineBreakMode=NSLineBreakByTruncatingTail;[_status setContentCompressionResistancePriority:250 forOrientation:NSLayoutConstraintOrientationHorizontal];[devices addArrangedSubview:_status];[_root addArrangedSubview:devices];[devices.widthAnchor constraintEqualToAnchor:_root.widthAnchor].active=YES;
 auto* heading=midiLabel(@"Learned mappings");heading.font=[NSFont systemFontOfSize:12 weight:NSFontWeightSemibold];[_root addArrangedSubview:heading];auto* learn=midiStack(true);_kind=[[VJPopup alloc]initWithFrame:NSZeroRect pullsDown:NO];[_kind addItemsWithTitles:@[@"Master",@"Effect",@"Color cast",@"Clip",@"Column",@"Parameter"]];midiSize(_kind,140);_kind.target=self;_kind.action=@selector(kindChanged:);[learn addArrangedSubview:_kind];_target=[[VJPopup alloc]initWithFrame:NSZeroRect pullsDown:NO];midiSize(_target,260);[learn addArrangedSubview:_target];auto learnButton=[NSButton buttonWithTitle:@"Learn" target:self action:@selector(learn:)];midiSize(learnButton,72);[learn addArrangedSubview:learnButton];[learn addArrangedSubview:[self button:@"Cancel" command:{{"action","midi_learn"},{"target",nullptr}}]];[_root addArrangedSubview:learn];_mappings=midiStack();[_root addArrangedSubview:_mappings];[self refresh];
 }return self;
}
- (VJMidiAction*)button:(NSString*)title command:(Json)command {auto* b=[[VJMidiAction alloc]init];b.title=title;b.bezelStyle=NSBezelStyleRounded;b.target=self;b.action=@selector(perform:);b->command=command;midiSize(b,72);return b;}
- (void)send:(Json)command {command["revision"]=_model->presentationSnapshot()["revision"];__weak VJMidiControls* weak=self;VJSubmitUiCommand(_model,"POST","/api/v1/midi",command,^(const vj::Reply& reply){VJMidiControls* owner=weak;if(!owner)return;if(reply.status>=400)owner->_status.stringValue=midiText(reply.body.value("error",std::string("Command failed")));else {owner->_revision=UINT64_MAX;[owner refresh];}});}
- (void)perform:(VJMidiAction*)sender {[self send:sender->command];}
- (void)deviceChanged:(id)sender {if(_building)return;[self send:{{"action","midi_select"},{"name",_devices.indexOfSelectedItem==0?Json():Json(_devices.titleOfSelectedItem.UTF8String)}}];}
- (void)kindChanged:(id)sender {_learnKind=std::array<const char*,6>{"mix_master","mix_effect","cast","grid_clip","grid_column","param"}[_kind.indexOfSelectedItem];[self targets:_model->presentationSnapshot()["state"]];}
- (void)addTarget:(NSString*)title target:(Json)target {[_target addItemWithTitle:title];_targets.push_back(target);}
- (void)targets:(const Json&)state {
 NSInteger selected=_target.indexOfSelectedItem;[_target removeAllItems];_targets.clear();auto g=state.at("grid");auto focus=g.value("control_focus",Json::object());std::string bus=focus.value("bus",std::string("program"));
 if(_learnKind=="mix_master"){[self addTarget:@"Video" target:{{"kind","mix_master"},{"which","video"}}];[self addTarget:@"LED" target:{{"kind","mix_master"},{"which","led"}}];}
 else if(_learnKind=="mix_effect")for(auto effect:{"pulse","strobe","invert","blackout","flash"})[self addTarget:midiText(effect) target:{{"kind","mix_effect"},{"effect",effect}}];
 else if(_learnKind=="cast")for(auto color:{"#ff0000","#ff8800","#ffff00","#00ff00","#00ffff","#0000ff","#8800ff","#ff00ff","#ffffff"})[self addTarget:midiText(color) target:{{"kind","cast"},{"cast",color}}];
 else if(_learnKind=="grid_column")for(auto& column:g["columns"])[self addTarget:midiText(column.value("name",column.value("id",std::string{}))) target:{{"kind","grid_column"},{"bus",bus},{"column",column["id"]}}];
 else if(_learnKind=="grid_clip")for(auto i=g["rows"].rbegin();i!=g["rows"].rend();++i)for(auto& column:g["columns"]){auto cid=column["id"].get<std::string>();if((*i)["clips"].contains(cid)){auto& clip=(*i)["clips"][cid];[self addTarget:midiText(i->value("name",std::string("Layer"))+" · "+clip.value("name",cid)) target:{{"kind","grid_clip"},{"bus",bus},{"row",(*i)["id"]},{"column",cid}}];}}
 else if(_learnKind=="param"){
  auto selected=g["selections"].value(bus,Json::object());int slot=0;auto catalog=_model->effectCatalog();for(auto& row:g["rows"]){auto rid=row["id"].get<std::string>();if(!selected.contains(rid)||!selected[rid].is_string())continue;auto cid=selected[rid].get<std::string>();if(!row["clips"].contains(cid))continue;auto clip=row["clips"][cid];auto prefix=row.value("name",rid)+" · ";[self addTarget:midiText(prefix+"Opacity") target:{{"kind","param"},{"bus",bus},{"slot",slot},{"param","_opacity"}}];for(auto& effect:catalog)if(effect["name"]==clip["gen"])for(auto& p:effect.value("parameters",Json::array())){auto kind=p.value("kind",std::string{});if(kind=="float"||kind=="bool"||kind=="choice")[self addTarget:midiText(prefix+p.value("label",p["name"].get<std::string>())) target:{{"kind","param"},{"bus",bus},{"slot",slot},{"param",p["name"]}}];}++slot;}
 }
 if(!_targets.empty())[_target selectItemAtIndex:std::clamp<NSInteger>(selected,0,_targets.size()-1)];
}
- (void)learn:(id)sender {if(_target.indexOfSelectedItem<0)return;[self send:{{"action","midi_learn"},{"target",_targets.at(_target.indexOfSelectedItem)}}];}
- (void)refresh {
 auto snapshot=_model->presentationSnapshot();auto revision=snapshot.value("revision",uint64_t(0)),runtimeRevision=snapshot.value("runtimeRevision",uint64_t(0));if(revision==_revision&&runtimeRevision==_runtimeRevision)return;_revision=revision;_runtimeRevision=runtimeRevision;_building=true;auto state=snapshot["state"],midi=state.value("midi",Json::object());std::string status=midi.value("status",std::string("Unavailable"));auto learning=midi.value("learning",Json());if(!learning.is_null())status+=" · Learning "+learning.value("kind",std::string{});auto error=midi.value("error",std::string{});if(!error.empty())status+=" · "+error;_status.stringValue=midiText(status);[_devices removeAllItems];[_devices addItemWithTitle:@"Off"];for(auto& input:midi.value("inputs",Json::array()))if(input.is_string())[_devices addItemWithTitle:midiText(input.get<std::string>())];auto selected=midi.value("selected",Json());if(selected.is_string()){auto name=midiText(selected.get<std::string>());if([_devices indexOfItemWithTitle:name]<0)[_devices addItemWithTitle:name];[_devices selectItemWithTitle:name];}else [_devices selectItemAtIndex:0];[self targets:state];for(NSView* child in _mappings.arrangedSubviews){[_mappings removeArrangedSubview:child];[child removeFromSuperview];}auto mappings=midi.value("mappings",Json::array());for(size_t i=0;i<mappings.size();i++){auto m=mappings[i];auto* row=midiStack(true);std::string binding=(m.value("type",std::string{})=="cc"?"CC "+std::to_string(m.value("cc",0)):"Note "+std::to_string(m.value("note",0)))+" · Ch "+std::to_string(m.value("channel",0)+1)+" · ";if(m.contains("mix"))binding+=m["mix"].get<std::string>()+" master";else if(m.contains("mix_effect"))binding+=m["mix_effect"].get<std::string>();else if(m.contains("cast"))binding+=m["cast"].get<std::string>();else if(m.contains("param"))binding+=m["param"].get<std::string>();else if(m.contains("grid"))binding+=m["grid"].value("action",std::string("grid"));[row addArrangedSubview:[NSTextField labelWithString:midiText(binding)]];[row addArrangedSubview:[self button:@"Unmap" command:{{"action","midi_unmap"},{"index",i}}]];[_mappings addArrangedSubview:row];}if(mappings.empty())[_mappings addArrangedSubview:[NSTextField labelWithString:@"No mappings"]];vj::style::apply(_root);_building=false;
}
@end
